// Stage 3 verification for child 02: real discovery on this Mac plus simulated platforms.
import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const dist = process.argv[2];
const runtime = await import(join(dist, "runtime.js"));
const install = await import(join(dist, "install.js"));
const platform = await import(join(dist, "platform.js"));

const summarize = (plan) =>
    plan.kind === "plan"
        ? {
              kind: plan.kind,
              platform: plan.platform,
              source: plan.source,
              command: plan.command,
              args: plan.args,
              configPath: plan.configPath,
              appPath: plan.appPath,
              appVersion: plan.appVersion,
              runtimeRoot: plan.runtimeRoot,
              nodeModules: plan.nodeModules,
              enabledTools: plan.enabledTools,
              outputTokenLimit: plan.outputTokenLimit,
              startupTimeoutSec: plan.startupTimeoutSec,
              isSimulated: plan.isSimulated,
              envKeys: Object.keys(plan.env).sort(),
          }
        : plan;

const section = (title) => console.log(`\n===== ${title}`);

// 1. Real discovery on this Mac.
section("1. real discovery (darwin)");
const real = await runtime.discoverRuntime();
console.log(JSON.stringify(summarize(real), null, 2));

// 2. Full prerequisite report on this Mac (runs setup.sh).
section("2. real prerequisites (runs setup.sh)");
const report = await install.checkPrerequisites();
console.log(install.formatPrerequisiteReport(report).join("\n"));
console.log("setupScript:", JSON.stringify({ ...report.setupScript, outputTail: report.setupScript?.outputTail?.slice(-200) }));

// 3. Simulated Linux: platform-unsupported without touching the filesystem.
section("3. simulated linux");
const linuxEnv = { ...process.env, PI_CODEX_COMPUTER_USE_PLATFORM: "linux" };
console.log(JSON.stringify(platform.detectPlatform(linuxEnv)));
console.log(JSON.stringify(await runtime.discoverRuntime({ env: linuxEnv })));

// 4. Simulated Windows plugin cache with Windows-style absolute paths.
section("4. simulated win32 with hand-written plugin cache");
const fakeHome = await mkdtemp(join(tmpdir(), "cua-02-codex-home-"));
const versionDir = join(fakeHome, "plugins", "cache", "openai-bundled", "unified-computer-use", "26.930.31730");
await mkdir(versionDir, { recursive: true });
await writeFile(
    join(versionDir, ".mcp.json"),
    JSON.stringify(
        {
            mcpServers: {
                cua_repl: {
                    command: "C:\\Users\\tester\\AppData\\Local\\Programs\\Codex\\resources\\cua_node\\bin\\node.exe",
                    args: ["C:\\Users\\tester\\AppData\\Local\\Programs\\Codex\\resources\\cua_node\\lib\\node_modules\\@oai\\cua-repl\\bin\\cua-repl.mjs"],
                    enabled: true,
                    enabled_tools: ["js", "js_reset", "turn_ended"],
                    startup_timeout_sec: 120,
                    tools: { js: { output_token_limit: 25000 } },
                    env: {
                        NODE_REPL_NODE_MODULE_DIRS: "C:\\Users\\tester\\AppData\\Local\\Programs\\Codex\\resources\\cua_node\\lib\\node_modules",
                        CODEX_HOME: "C:\\Users\\tester\\.codex",
                        CUA_REPL_ENABLED_SURFACES: "browser,computer",
                        NODE_REPL_TRUSTED_SERVICES: '{"browser":"@oai/browser-desktop/service","sky":"@oai/sky/service"}',
                        BROWSER_USE_CODEX_APP_VERSION: "26.930.31730",
                    },
                },
            },
        },
        null,
        2,
    ),
);
const winEnv = { ...process.env, PI_CODEX_COMPUTER_USE_PLATFORM: "win32", CODEX_HOME: fakeHome };
console.log(JSON.stringify(summarize(await runtime.discoverRuntime({ env: winEnv })), null, 2));
const winReport = await install.checkPrerequisites({ env: winEnv });
console.log(install.formatPrerequisiteReport(winReport).join("\n"));

// 5. Simulated Windows without a plugin cache.
section("5. simulated win32 with empty CODEX_HOME");
const emptyHome = await mkdtemp(join(tmpdir(), "cua-02-empty-home-"));
console.log(JSON.stringify(await runtime.discoverRuntime({ env: { ...process.env, PI_CODEX_COMPUTER_USE_PLATFORM: "win32", CODEX_HOME: emptyHome } }), null, 2));

// 6. darwin, empty CODEX_HOME, missing app → app-not-found.
section("6. darwin, empty CODEX_HOME, PI_CODEX_COMPUTER_USE_APP_PATH=/nonexistent");
console.log(JSON.stringify(await runtime.discoverRuntime({ env: { ...process.env, CODEX_HOME: emptyHome, PI_CODEX_COMPUTER_USE_APP_PATH: "/nonexistent" } }), null, 2));

// 7. darwin, empty CODEX_HOME → app-bundle fallback; compare env keys with the real plan.
section("7. darwin app-bundle fallback (empty CODEX_HOME)");
const fallback = await runtime.discoverRuntime({ env: { ...process.env, CODEX_HOME: emptyHome } });
console.log(JSON.stringify(summarize(fallback), null, 2));
if (real.kind === "plan" && fallback.kind === "plan") {
    const realKeys = new Set(Object.keys(real.env));
    const fallbackKeys = new Set(Object.keys(fallback.env));
    const onlyReal = [...realKeys].filter((k) => !fallbackKeys.has(k));
    const onlyFallback = [...fallbackKeys].filter((k) => !realKeys.has(k));
    console.log("keys only in real .mcp.json plan:", onlyReal);
    console.log("keys only in fallback plan:", onlyFallback);
    const differing = [...realKeys].filter((k) => fallbackKeys.has(k) && real.env[k] !== fallback.env[k]);
    console.log("shared keys with different values:", differing.map((k) => `${k}: ${real.env[k]} -> ${fallback.env[k]}`));
    console.log("command equal:", real.command === fallback.command, "args equal:", JSON.stringify(real.args) === JSON.stringify(fallback.args));
}

await rm(fakeHome, { recursive: true, force: true });
await rm(emptyHome, { recursive: true, force: true });

// Drives pi in RPC mode: sends /codex-computer-use prompts, answers select dialogs with cancel,
// and prints every record. Usage: node rpc-driver.mjs <pi-binary> <pi args...>
import { spawn } from "node:child_process";

const [piBinary, ...piArgs] = process.argv.slice(2);
const steps = [
    "/codex-computer-use status",
    "/codex-computer-use browser off",
    "/codex-computer-use status",
    "/codex-computer-use",
    "/codex-computer-use browser on",
    "/codex-computer-use bogus",
    "/codex-computer-use check",
];
let stepIndex = 0;
const child = spawn(piBinary, piArgs, { stdio: ["pipe", "pipe", "pipe"] });
child.stderr.on("data", (chunk) => process.stdout.write(`[stderr] ${chunk}`));
const send = (record) => {
    console.log(`>>> ${JSON.stringify(record)}`);
    child.stdin.write(`${JSON.stringify(record)}\n`);
};
const next = () => {
    if (stepIndex >= steps.length) {
        setTimeout(() => {
            send({ type: "abort" });
            child.kill("SIGTERM");
        }, 500);
        return;
    }
    const id = `step-${stepIndex + 1}`;
    const message = steps[stepIndex];
    stepIndex += 1;
    send({ id, type: "prompt", message });
};
let buffer = "";
child.stdout.on("data", (chunk) => {
    buffer += chunk.toString();
    let newline = buffer.indexOf("\n");
    while (newline !== -1) {
        const line = buffer.slice(0, newline).trim();
        buffer = buffer.slice(newline + 1);
        newline = buffer.indexOf("\n");
        if (!line) continue;
        let record;
        try {
            record = JSON.parse(line);
        } catch {
            console.log(`<<< (raw) ${line}`);
            continue;
        }
        if (record.type === "extension_ui_request") {
            if (record.method === "notify") {
                console.log(`<<< notify[${record.notifyType ?? record.type}] ${JSON.stringify(record.message ?? record)}`);
            } else if (record.method === "select") {
                console.log(`<<< select title=${JSON.stringify(record.title)} options=${JSON.stringify(record.options)}`);
                send({ type: "extension_ui_response", id: record.id, cancelled: true });
            } else {
                console.log(`<<< ui ${JSON.stringify(record)}`);
            }
            continue;
        }
        if (record.type === "response") {
            console.log(`<<< response ${JSON.stringify(record)}`);
            if (record.command === "prompt") next();
            continue;
        }
        console.log(`<<< event ${record.type}${record.type === "agent_end" ? "" : ""}`);
    }
});
child.on("exit", (code, signal) => {
    console.log(`pi exited code=${code} signal=${signal}`);
});
setTimeout(next, 1500);
setTimeout(() => {
    console.log("timeout: killing pi");
    child.kill("SIGKILL");
}, 120_000).unref();
